//! Hooks owned by the repository's `.githooks/` cache-gate installer.
//!
//! `scripts/dev/install-pre-push-cache-gate.sh` installs each managed
//! `.githooks/<name>` and refuses when an active hook exists and differs.
//! A hook generated by `pre-commit install` for the same type (for example a
//! repository whose `default_install_hook_types` includes `post-commit`) is
//! superseded by the repository's own hook, so it is removed first. Any other
//! custom hook is kept, so the installer still refuses it.
use anyhow::{Context, Result};
use std::path::Path;

/// Hook types the cache-gate installer manages from `.githooks/`.
pub(super) const MANAGED: [&str; 2] = ["post-commit", "pre-push"];
const PRE_COMMIT_MARKER: &str = "File generated by pre-commit";

/// Returns whether `.githooks/<name>` exists, i.e. the installer owns `name`.
pub(super) fn owns(repo_path: &Path, name: &str) -> bool {
    repo_path.join(".githooks").join(name).is_file()
}

/// Remove stale pre-commit-generated hooks the cache-gate installer manages.
///
/// # Errors
/// Returns hook directory lookup or file removal errors.
pub(super) async fn remove_superseded(repo_path: &Path) -> Result<()> {
    let hooks = hooks_dir(repo_path).await?;
    for name in MANAGED.into_iter().filter(|name| owns(repo_path, name)) {
        let active = hooks.join(name);
        if superseded(&active, &repo_path.join(".githooks").join(name)) {
            std::fs::remove_file(&active)
                .with_context(|| format!("Failed to remove {}", active.display()))?;
            tracing::info!(hook = %active.display(), "Removed pre-commit hook superseded by .githooks");
        }
    }
    Ok(())
}

fn superseded(active: &Path, owned: &Path) -> bool {
    let Ok(meta) = std::fs::symlink_metadata(active) else {
        return false;
    };
    if meta.file_type().is_symlink() {
        return false;
    }
    match (std::fs::read(active), std::fs::read(owned)) {
        (Ok(current), Ok(wanted)) => {
            current != wanted && String::from_utf8_lossy(&current).contains(PRE_COMMIT_MARKER)
        }
        _ => false,
    }
}

async fn hooks_dir(repo_path: &Path) -> Result<std::path::PathBuf> {
    let path = crate::repository::git::run_git_command_at(
        Some(repo_path),
        vec![
            "rev-parse".into(),
            "--path-format=absolute".into(),
            "--git-path".into(),
            "hooks".into(),
        ],
    )
    .await
    .context("Failed to resolve the active hooks directory")?;
    Ok(path.trim().into())
}
